import React, { useState } from 'react';
import { Button, message } from 'antd';
import { DownloadOutlined } from '@ant-design/icons';
import api from '../api/axiosInstance';

const ExportCsvButton = ({ module, moduleName }) => {
  const [loading, setLoading] = useState(false);

  const handleExport = async () => {
    setLoading(true);
    const hide = message.loading(`Preparing ${moduleName} export...`, 0);
    try {
      const res = await api.get(`/${module}/export`, { responseType: 'blob' });
      const url = window.URL.createObjectURL(new Blob([res.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `${module}.csv`);
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
      message.success(`${moduleName} exported successfully`);
    } catch (error) {
      // ignore error
      message.error(`Failed to export ${moduleName}`);
    } finally {
      hide();
      setLoading(false);
    }
  };

  return (
    <Button 
      icon={<DownloadOutlined />} 
      onClick={handleExport} 
      loading={loading}
    >
      Export
    </Button>
  );
};

export default ExportCsvButton;

import { useState, useEffect } from 'react';
import { Table, Button, Space, Input, InputNumber, Select, Tag, Form, Tabs, Popconfirm, Spin, Card, Row, Col, Divider } from 'antd';
import { PlusOutlined, EditOutlined, StopOutlined, CheckCircleOutlined, SearchOutlined, DeleteOutlined, EyeOutlined, UploadOutlined } from '@ant-design/icons';
import { useQueryClient } from '@tanstack/react-query';
import PageHeader from '../../components/PageHeader';
import FormModal from '../../components/FormModal';
import CompanyViewDrawer from '../../components/CompanyViewDrawer';
import ColumnSelector from '../../components/ColumnSelector';
import StatusBadge from '../../components/StatusBadge';
import PermissionGuard from '../../components/PermissionGuard';
import ExportCsvButton from '../../components/ExportCsvButton';
import BulkImportModal from '../../components/BulkImportModal';
import LocationFields from '../../components/LocationFields';
import {
  useCompanies, useCompany,
  useCreateCompany, useUpdateCompany,
  useDeactivateCompany, useReactivateCompany
} from '../../api/companiesApi';
import { useUploadDocument } from '../../api/documentsApi';
import useFormErrors from '../../hooks/useFormErrors';
import useColumnVisibility from '../../hooks/useColumnVisibility';
import { message } from 'antd';

const COMPANY_TYPES = [
  { value: 'MANUFACTURER', label: 'Manufacturer', color: 'blue' },
  { value: 'SUPPLIER', label: 'Supplier', color: 'green' },
  { value: 'BUYER', label: 'Buyer', color: 'orange' },
  { value: 'DISTRIBUTOR', label: 'Distributor', color: 'purple' },
];

function CompaniesPage() {
  const queryClient = useQueryClient();
  const [form] = Form.useForm();
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState('');
  const [filterType, setFilterType] = useState('');
  const [filterStatus, setFilterStatus] = useState('');
  const [modalOpen, setModalOpen] = useState(false);
  const [importOpen, setImportOpen] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [viewId, setViewId] = useState(null);

  const { data: listData, isLoading } = useCompanies({ page, search, company_type: filterType, status: filterStatus });
  const { data: editData } = useCompany(editingId);
  const { mutate: create, isPending: creating } = useCreateCompany();
  const { mutate: update, isPending: updating } = useUpdateCompany();
  const { mutate: deactivate } = useDeactivateCompany();
  const { mutate: reactivate } = useReactivateCompany();
  const { mutateAsync: uploadDoc } = useUploadDocument();
  const { applyServerErrors } = useFormErrors(form);

  const [uploadFiles, setUploadFiles] = useState([]);

  useEffect(() => {
    if (editData && editingId) {
      form.setFieldsValue({
        ...editData,
        branches: editData.branches || [],
      });
    }
  }, [editData, editingId, form]);

  const handleAdd = () => {
    setEditingId(null);
    form.resetFields();
    form.setFieldsValue({ branches: [] });
    setUploadFiles([]);
    setModalOpen(true);
  };

  const handleEdit = (record) => {
    setEditingId(record.company_id);
    setModalOpen(true);
  };

  const handleSubmit = (values) => {
    if (editingId) {
      update({ id: editingId, data: values }, {
        onSuccess: () => { setModalOpen(false); setEditingId(null); },
        onError: (err) => {
          applyServerErrors(err);
          if (!err?.response?.data?.errors?.length) {
            message.error(err?.response?.data?.message || 'Failed to update company');
          }
        }
      });
    } else {
      create(values, {
        onSuccess: async (res) => { 
          const companyId = res?.data?.data?.company_id;
          if (companyId && uploadFiles.length > 0) {
            for (let file of uploadFiles) {
              const formData = new FormData();
              formData.append('file', file.originFileObj || file);
              formData.append('entity_type', 'COMPANY');
              formData.append('entity_id', companyId);
              try { await uploadDoc(formData); } catch (e) { /* ignore */ }
            }
          }
          setModalOpen(false); 
          setUploadFiles([]);
        },
        onError: (err) => {
          applyServerErrors(err);
          if (!err?.response?.data?.errors?.length) {
            message.error(err?.response?.data?.message || 'Failed to create company');
          }
        }
      });
    }
  };

  const handleImportSuccess = () => {
    queryClient.invalidateQueries({ queryKey: ['companies'] });
  };

  const allColumns = [
    { title: 'Company Name', dataIndex: 'company_name', key: 'company_name', width: 200 },
    {
      title: 'Type', key: 'company_type', width: 130,
      render: (_, r) => {
        const t = COMPANY_TYPES.find(ct => ct.value === r.company_type);
        return <Tag color={t?.color}>{t?.label || r.company_type}</Tag>;
      }
    },
    { title: 'Email', dataIndex: 'email', key: 'email', width: 180 },
    { title: 'Phone', dataIndex: 'phone', key: 'phone', width: 130 },
    { title: 'GST', dataIndex: 'gst_number', key: 'gst', width: 160 },
    { title: 'Branches', key: 'branches', width: 80, align: 'center', render: (_, r) => r._count?.branches || 0 },
    { title: 'Status', key: 'status', width: 100, render: (_, r) => <StatusBadge status={r.status} /> },
    {
      title: 'Actions', key: 'actions', width: 200,
      render: (_, record) => (
        <Space>
          <PermissionGuard module="companies" action="can_view">
            <Button size="small" icon={<EyeOutlined />} onClick={() => setViewId(record.company_id)}>View</Button>
          </PermissionGuard>
          <PermissionGuard module="companies" action="can_edit">
            <Button size="small" icon={<EditOutlined />} onClick={() => handleEdit(record)}>Edit</Button>
          </PermissionGuard>
          <PermissionGuard module="companies" action="can_delete">
            {record.status === 'ACTIVE' ? (
              <Popconfirm title="Deactivate this company and all its mappings?" onConfirm={() => deactivate(record.company_id)}>
                <Button size="small" danger icon={<StopOutlined />}>Deactivate</Button>
              </Popconfirm>
            ) : (
              <Button size="small" icon={<CheckCircleOutlined />} onClick={() => reactivate(record.company_id)}>Reactivate</Button>
            )}
          </PermissionGuard>
        </Space>
      ),
    },
  ];

  const { visibleColumns, toggleColumn, hiddenKeys } = useColumnVisibility(allColumns, []);

  const formTabs = [
    {
      key: 'details',
      label: 'Company Details',
      children: (
        <Row gutter={16}>
          <Col span={12}>
            <Form.Item name="company_name" label="Company Name" rules={[{ required: true }]}><Input /></Form.Item>
          </Col>
          <Col span={12}>
            <Form.Item name="company_type" label="Company Type" rules={[{ required: true }]}>
              <Select options={COMPANY_TYPES} />
            </Form.Item>
          </Col>
          <Col span={24}>
            <Form.Item name="address" label="Address"><Input.TextArea rows={2} /></Form.Item>
          </Col>
          <LocationFields namePrefix={[]} colSpan={8} />
          <Col span={12}><Form.Item name="email" label="Email" rules={[{ type: 'email', message: 'Invalid email format' }]}><Input /></Form.Item></Col>
          <Col span={12}><Form.Item name="phone" label="Phone" rules={[{ pattern: /^[0-9]{10,15}$/, message: 'Must be 10-15 digits' }]}><Input /></Form.Item></Col>
          <Col span={8}><Form.Item name="gst_number" label="GST Number"><Input maxLength={15} /></Form.Item></Col>
          <Col span={8}><Form.Item name="pan_number" label="PAN Number"><Input maxLength={10} /></Form.Item></Col>
          <Col span={8}><Form.Item name="cin_number" label="CIN Number"><Input /></Form.Item></Col>
          <Col span={12}><Form.Item name="website" label="Website"><Input /></Form.Item></Col>
          <Col span={12}><Form.Item name="industry_type" label="Industry Type"><Input /></Form.Item></Col>
          <Col span={24}><Form.Item name="remarks" label="Remarks"><Input.TextArea rows={2} /></Form.Item></Col>
          {!editingId && (
            <Col span={24}>
              <Divider style={{ margin: '12px 0' }} />
              <Form.Item label="Initial Documents">
                <Input type="file" multiple onChange={(e) => setUploadFiles(Array.from(e.target.files))} />
              </Form.Item>
            </Col>
          )}
        </Row>
      ),
    },
    {
      key: 'branches',
      label: 'Branches',
      children: (
        <Form.List name="branches">
          {(fields, { add, remove }) => (
            <>
              {fields.map(({ key, name, ...restField }) => (
                <Card key={key} size="small" style={{ marginBottom: 12 }}
                  extra={<Button type="text" danger icon={<DeleteOutlined />} onClick={() => remove(name)} />}
                  title={`Branch ${name + 1}`}
                >
                  <Row gutter={12}>
                    <Col span={12}><Form.Item {...restField} name={[name, 'branch_name']} label="Branch Name" rules={[{ required: true }]}><Input /></Form.Item></Col>
                    <Col span={12}><Form.Item {...restField} name={[name, 'gst_number']} label="GST"><Input maxLength={15} /></Form.Item></Col>
                    <Col span={12}><Form.Item {...restField} name={[name, 'address_line1']} label="Address Line 1"><Input /></Form.Item></Col>
                    <Col span={12}><Form.Item {...restField} name={[name, 'address_line2']} label="Address Line 2"><Input /></Form.Item></Col>
                    <LocationFields restField={restField} namePrefix={[name]} />
                    <Col span={8}><Form.Item {...restField} name={[name, 'pincode']} label="Pincode"><Input /></Form.Item></Col>
                    <Col span={8}><Form.Item {...restField} name={[name, 'contact_number']} label="Contact Number" rules={[{ pattern: /^[0-9]{10,15}$/, message: 'Must be 10-15 digits' }]}><Input /></Form.Item></Col>
                    <Col span={8}><Form.Item {...restField} name={[name, 'email']} label="Email" rules={[{ type: 'email', message: 'Invalid email format' }]}><Input /></Form.Item></Col>
                    <Col span={4}><Form.Item {...restField} name={[name, 'latitude']} label="Latitude" rules={[{ type: 'number', min: -90, max: 90, message: 'Must be between -90 and 90' }]}><InputNumber style={{ width: '100%' }} /></Form.Item></Col>
                    <Col span={4}><Form.Item {...restField} name={[name, 'longitude']} label="Longitude" rules={[{ type: 'number', min: -180, max: 180, message: 'Must be between -180 and 180' }]}><InputNumber style={{ width: '100%' }} /></Form.Item></Col>
                  </Row>
                  <Form.Item {...restField} name={[name, 'branch_id']} hidden><Input /></Form.Item>
                </Card>
              ))}
              <Button type="dashed" onClick={() => add()} block icon={<PlusOutlined />}>Add Branch</Button>
            </>
          )}
        </Form.List>
      ),
    },
  ];

  return (
    <div>
      <PageHeader
        title="Companies"
        subtitle="Manage manufacturers, suppliers, buyers and distributors"
        breadcrumbs={['Companies']}
        extra={
          <Space>
            <ExportCsvButton module="companies" moduleName="Companies" />
            <PermissionGuard module="companies" action="can_create">
              <Button icon={<UploadOutlined />} onClick={() => setImportOpen(true)}>Import</Button>
            </PermissionGuard>
            <PermissionGuard module="companies" action="can_create">
              <Button type="primary" icon={<PlusOutlined />} onClick={handleAdd} style={{ background: '#1F3A6E' }}>
                Add Company
              </Button>
            </PermissionGuard>
          </Space>
        }
      />

      <Space style={{ marginBottom: 16, width: '100%', justifyContent: 'space-between' }} wrap>
        <Input.Search
          placeholder="Search by name, email, GST, or mapped product..."
          allowClear onSearch={(v) => { setSearch(v); setPage(1); }}
          style={{ width: 350 }} prefix={<SearchOutlined />}
        />
        <Space>
          <Select placeholder="Company Type" allowClear style={{ width: 160 }}
            value={filterType || undefined} onChange={(v) => { setFilterType(v || ''); setPage(1); }}
            options={COMPANY_TYPES}
          />
          <Select placeholder="Status" allowClear style={{ width: 120 }}
            value={filterStatus || undefined} onChange={(v) => { setFilterStatus(v || ''); setPage(1); }}
            options={[{ value: 'ACTIVE', label: 'Active' }, { value: 'INACTIVE', label: 'Inactive' }]}
          />
          <ColumnSelector columns={allColumns} hiddenKeys={hiddenKeys} onToggle={toggleColumn} />
        </Space>
      </Space>

      <Table
        columns={visibleColumns} dataSource={listData?.data || []}
        loading={isLoading} rowKey="company_id"
        pagination={{
          current: page, total: listData?.pagination?.total || 0, pageSize: 20,
          showSizeChanger: false, showTotal: (t) => `Total ${t} companies`, onChange: setPage,
        }}
        size="middle"
      />

      <FormModal open={modalOpen} onClose={() => { setModalOpen(false); setEditingId(null); }}
        onSubmit={handleSubmit} title={editingId ? 'Edit Company' : 'Add Company'}
        loading={creating || updating} width={800} form={form}
      >
        <Tabs items={formTabs} />
      </FormModal>

      <CompanyViewDrawer open={!!viewId} companyId={viewId} onClose={() => setViewId(null)} />

      <BulkImportModal
        open={importOpen}
        onClose={() => setImportOpen(false)}
        module="companies"
        moduleName="Companies"
        onImportSuccess={handleImportSuccess}
      />
    </div>
  );
}

export default CompaniesPage;

import { useState, useEffect } from 'react';
import { Table, Button, Space, Input, Select, Tag, Form, Tabs, InputNumber, Popconfirm, Spin, Divider } from 'antd';
import { PlusOutlined, EditOutlined, StopOutlined, CheckCircleOutlined, SearchOutlined, EyeOutlined, UploadOutlined } from '@ant-design/icons';
import { useQueryClient } from '@tanstack/react-query';
import PageHeader from '../../components/PageHeader';
import FormModal from '../../components/FormModal';
import ProductViewDrawer from '../../components/ProductViewDrawer';
import ColumnSelector from '../../components/ColumnSelector';
import StatusBadge from '../../components/StatusBadge';
import PermissionGuard from '../../components/PermissionGuard';
import ExportCsvButton from '../../components/ExportCsvButton';
import BulkImportModal from '../../components/BulkImportModal';
import {
  useProducts, useProduct, useProductFormData,
  useCreateProduct, useUpdateProduct,
  useDeactivateProduct, useReactivateProduct
} from '../../api/productsApi';
import { useUploadDocument } from '../../api/documentsApi';
import useFormErrors from '../../hooks/useFormErrors';
import useColumnVisibility from '../../hooks/useColumnVisibility';
import { message } from 'antd';

function ProductsPage() {
  const queryClient = useQueryClient();
  const [form] = Form.useForm();
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState('');
  const [filterCategory, setFilterCategory] = useState('');
  const [filterGrade, setFilterGrade] = useState('');
  const [filterStatus, setFilterStatus] = useState('');
  const [modalOpen, setModalOpen] = useState(false);
  const [importOpen, setImportOpen] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [viewId, setViewId] = useState(null);

  const { data: listData, isLoading } = useProducts({ page, search, category_id: filterCategory, grade_id: filterGrade, status: filterStatus });
  const { data: editData } = useProduct(editingId);
  const { data: formData } = useProductFormData();
  const { mutate: create, isPending: creating } = useCreateProduct();
  const { mutate: update, isPending: updating } = useUpdateProduct();
  const { mutate: deactivate } = useDeactivateProduct();
  const { mutate: reactivate } = useReactivateProduct();
  const { mutateAsync: uploadDoc } = useUploadDocument();

  const { applyServerErrors } = useFormErrors(form);

  const [uploadFiles, setUploadFiles] = useState([]);

  useEffect(() => {
    if (editData && editingId) {
      form.setFieldsValue(editData);
    }
  }, [editData, editingId, form]);

  const handleAdd = () => {
    setEditingId(null);
    form.resetFields();
    setUploadFiles([]);
    setModalOpen(true);
  };

  const handleEdit = (record) => {
    setEditingId(record.product_id);
    setModalOpen(true);
  };

  const handleSubmit = (values) => {
    if (editingId) {
      update({ id: editingId, data: values }, {
        onSuccess: () => { setModalOpen(false); setEditingId(null); },
        onError: (err) => {
          applyServerErrors(err);
          if (!err?.response?.data?.errors?.length) {
            message.error(err?.response?.data?.message || 'Failed to update product');
          }
        }
      });
    } else {
      create(values, {
        onSuccess: async (res) => { 
          const productId = res?.data?.data?.product_id;
          if (productId && uploadFiles.length > 0) {
            for (let file of uploadFiles) {
              const formData = new FormData();
              formData.append('file', file.originFileObj || file);
              formData.append('entity_type', 'PRODUCT');
              formData.append('entity_id', productId);
              try { await uploadDoc(formData); } catch (e) { /* ignore */ }
            }
          }
          setModalOpen(false); 
          setUploadFiles([]);
        },
        onError: (err) => {
          applyServerErrors(err);
          if (!err?.response?.data?.errors?.length) {
            message.error(err?.response?.data?.message || 'Failed to create product');
          }
        }
      });
    }
  };

  const handleImportSuccess = () => {
    queryClient.invalidateQueries({ queryKey: ['products'] });
  };

  const allColumns = [
    { title: 'Product Name', dataIndex: 'product_name', key: 'product_name', width: 200 },
    { title: 'SKU', dataIndex: 'sku', key: 'sku', width: 120 },
    { title: 'CAS Number', dataIndex: 'cas_number', key: 'cas_number', width: 130 },
    { title: 'Category', key: 'category', width: 130, render: (_, r) => r.category?.category_name || '—' },
    { title: 'Grade', key: 'grade', width: 100, render: (_, r) => r.grade?.grade_name || '—' },
    { title: 'UOM', dataIndex: 'unit_of_measure', key: 'uom', width: 70 },
    { title: 'Status', key: 'status', width: 100, render: (_, r) => <StatusBadge status={r.status} /> },
    {
      title: 'Actions', key: 'actions', width: 200,
      render: (_, record) => (
        <Space>
          <PermissionGuard module="products" action="can_view">
            <Button size="small" icon={<EyeOutlined />} onClick={() => setViewId(record.product_id)}>View</Button>
          </PermissionGuard>
          <PermissionGuard module="products" action="can_edit">
            <Button size="small" icon={<EditOutlined />} onClick={() => handleEdit(record)}>Edit</Button>
          </PermissionGuard>
          <PermissionGuard module="products" action="can_delete">
            {record.status === 'ACTIVE' ? (
              <Popconfirm title="Deactivate this product?" onConfirm={() => deactivate(record.product_id)}>
                <Button size="small" danger icon={<StopOutlined />}>Deactivate</Button>
              </Popconfirm>
            ) : (
              <Button size="small" icon={<CheckCircleOutlined />} onClick={() => reactivate(record.product_id)}>Reactivate</Button>
            )}
          </PermissionGuard>
        </Space>
      ),
    },
  ];

  const { visibleColumns, toggleColumn, hiddenKeys } = useColumnVisibility(allColumns, []);

  const filterBar = (
    <Space wrap>
      <Select
        placeholder="Category" allowClear style={{ width: 160 }}
        value={filterCategory || undefined} onChange={(v) => { setFilterCategory(v || ''); setPage(1); }}
        options={(formData?.categories || []).map(c => ({ value: c.category_id, label: c.category_name }))}
      />
      <Select
        placeholder="Grade" allowClear style={{ width: 140 }}
        value={filterGrade || undefined} onChange={(v) => { setFilterGrade(v || ''); setPage(1); }}
        options={(formData?.grades || []).map(g => ({ value: g.grade_id, label: g.grade_name }))}
      />
      <Select
        placeholder="Status" allowClear style={{ width: 120 }}
        value={filterStatus || undefined} onChange={(v) => { setFilterStatus(v || ''); setPage(1); }}
        options={[{ value: 'ACTIVE', label: 'Active' }, { value: 'INACTIVE', label: 'Inactive' }]}
      />
    </Space>
  );

  const formTabs = [
    {
      key: 'basic',
      label: 'Basic Info',
      children: (
        <>
          <Form.Item name="product_name" label="Product Name" rules={[
            { required: true, message: 'Product name is required' },
            { max: 255, message: 'Cannot exceed 255 characters' },
            { whitespace: true, message: 'Product name cannot be blank spaces' }
          ]}>
            <Input />
          </Form.Item>
          <Form.Item name="sku" label="SKU" rules={[
            { required: true },
            { max: 100, message: 'SKU cannot exceed 100 characters' },
            { pattern: /^[a-zA-Z0-9\-_\/\.]+$/, message: 'SKU can only contain letters, numbers, and -_/.' }
          ]}>
            <Input />
          </Form.Item>
          <Form.Item name="composition" label="Composition">
            <Input />
          </Form.Item>
          <Form.Item name="cas_number" label="CAS Number" rules={[{ pattern: /^\d{2,7}-\d{2}-\d{1}$/, message: 'Format: XXXXXXX-XX-X (e.g. 67-64-1)' }]}>
            <Input />
          </Form.Item>
          <Form.Item name="category_id" label="Category">
            <Select allowClear placeholder="Select category"
              options={(formData?.categories || []).map(c => ({ value: c.category_id, label: c.category_name }))}
            />
          </Form.Item>
          <Form.Item name="grade_id" label="Grade">
            <Select allowClear placeholder="Select grade"
              options={(formData?.grades || []).map(g => ({ value: g.grade_id, label: g.grade_name }))}
            />
          </Form.Item>
          <Form.Item name="packaging_id" label="Packaging">
            <Select allowClear placeholder="Select packaging"
              options={(formData?.packaging || []).map(p => ({ value: p.packaging_id, label: `${p.packaging_name} (${p.size_value} ${p.size_unit})` }))}
            />
          </Form.Item>
          <Form.Item name="unit_of_measure" label="Unit of Measure">
            <Select allowClear placeholder="Select UOM"
              options={[{ value: 'KG', label: 'KG' }, { value: 'LITRE', label: 'Litre' }, { value: 'TON', label: 'Ton' }]}
            />
          </Form.Item>
        </>
      ),
    },
    {
      key: 'business',
      label: 'Business Info',
      children: (
        <>
          <Form.Item name="hsn_code" label="HSN Code"><Input /></Form.Item>
          <Form.Item name="shelf_life" label="Shelf Life"><Input placeholder="e.g. 24 months" /></Form.Item>
          <Form.Item name="industry_application" label="Industry Application"><Input.TextArea rows={3} /></Form.Item>
          <Form.Item name="description" label="Description"><Input.TextArea rows={4} /></Form.Item>
          {!editingId && (
            <>
              <Divider style={{ margin: '12px 0' }} />
              <Form.Item label="Initial Documents">
                <Input type="file" multiple onChange={(e) => setUploadFiles(Array.from(e.target.files))} />
              </Form.Item>
            </>
          )}
        </>
      ),
    },
  ];

  return (
    <div>
      <PageHeader
        title="Products"
        subtitle="Manage product catalog"
        breadcrumbs={['Products']}
        extra={
          <Space>
            <ExportCsvButton module="products" moduleName="Products" />
            <PermissionGuard module="products" action="can_create">
              <Button icon={<UploadOutlined />} onClick={() => setImportOpen(true)}>Import</Button>
            </PermissionGuard>
            <PermissionGuard module="products" action="can_create">
              <Button type="primary" icon={<PlusOutlined />} onClick={handleAdd} style={{ background: '#1F3A6E' }}>
                Add Product
              </Button>
            </PermissionGuard>
          </Space>
        }
      />

      <Space style={{ marginBottom: 16, width: '100%', justifyContent: 'space-between' }} wrap>
        <Input.Search
          placeholder="Search by name, SKU, CAS, or mapped company..."
          allowClear
          onSearch={(v) => { setSearch(v); setPage(1); }}
          style={{ width: 350 }}
          prefix={<SearchOutlined />}
        />
        <Space>
          {filterBar}
          <ColumnSelector columns={allColumns} hiddenKeys={hiddenKeys} onToggle={toggleColumn} />
        </Space>
      </Space>

      <Table
        columns={visibleColumns}
        dataSource={listData?.data || []}
        loading={isLoading}
        rowKey="product_id"
        pagination={{
          current: page,
          total: listData?.pagination?.total || 0,
          pageSize: 20,
          showSizeChanger: false,
          showTotal: (t) => `Total ${t} products`,
          onChange: setPage,
        }}
        size="middle"
      />

      <FormModal
        open={modalOpen}
        onClose={() => { setModalOpen(false); setEditingId(null); }}
        onSubmit={handleSubmit}
        title={editingId ? 'Edit Product' : 'Add Product'}
        loading={creating || updating}
        width={720}
        form={form}
      >
        <Tabs items={formTabs} />
      </FormModal>

      <ProductViewDrawer open={!!viewId} productId={viewId} onClose={() => setViewId(null)} />

      <BulkImportModal
        open={importOpen}
        onClose={() => setImportOpen(false)}
        module="products"
        moduleName="Products"
        onImportSuccess={handleImportSuccess}
      />
    </div>
  );
}

